const sun=new T.DirectionalLight('#fff1d5',2.8);sun.position.copy(coords([center[0]-span,center[1]+span*.3,center[2]+span]));sun.target.position.copy(coords(center));scene.add(sun,sun.target);sun.castShadow=true;sun.shadow.camera.left=-span;sun.shadow.camera.right=span;sun.shadow.camera.top=span;sun.shadow.camera.bottom=-span;sun.shadow.camera.near=1;sun.shadow.camera.far=span*4;sun.shadow.bias=-.00012;sun.shadow.normalBias=.035;
