const groups=new Map(),mats={},textureCache=new Map(),buckets=new Map(),prismBuckets=new Map(),motionRoots=new Map(),motionInstances=new Map();const temp=new T.Object3D();let data,transition=null,dynamicLights=[],experience=null;
function motionRoot(id){if(!motionRoots.has(id)){const g=new T.Group();g.name=id;scene.add(g);motionRoots.set(id,g);}return motionRoots.get(id);}
